var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

function drawArrow(ctx, ox, oy, vx, vy, color) {
  var ex = ox + vx, ey = oy - vy;
  ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 4;
  ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(ex, ey); ctx.stroke();
  var angle = Math.atan2(oy - ey, ex - ox);
  var hl = 12;
  ctx.beginPath();
  ctx.moveTo(ex, ey);
  ctx.lineTo(ex - hl * Math.cos(angle - Math.PI/6), ey + hl * Math.sin(angle - Math.PI/6));
  ctx.lineTo(ex - hl * Math.cos(angle + Math.PI/6), ey + hl * Math.sin(angle + Math.PI/6));
  ctx.closePath(); ctx.fill();
}
return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    var ox = W * 0.2, oy = H * 0.8;
    var angle = Math.PI / 4;
    var mag = Math.min(W, H) * 0.15 + Math.min(W, H) * 0.12 * (0.5 + 0.5 * Math.sin(t * 0.02));
    var vx = mag * Math.cos(angle), vy = mag * Math.sin(angle);
    drawArrow(ctx, ox, oy, vx, vy, '#E8593C');
    ctx.fillStyle = '#333';
    ctx.font = '16px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('|v| = ' + mag.toFixed(0) + ' px  (length of the arrow only - direction fixed)', 10, 24);
  }
};
